from __future__ import annotations; from uuid import uuid4; import pytest; from sqlalchemy.ext.asyncio import AsyncSession
async def test_validation_does_not_pass_vacuously_when_closing_balance_missing(db: AsyncSession, test_user): from src.extraction import BankStatementStatus; from src.extraction.extension.statement_validation import validate_balance_chain; from src.extraction.orm.statement_summary import StatementSummary; statement = StatementSummary(user_id=test_user.id, file_hash=uuid4().hex, institution='SynthBank', currency='SGD', opening_balance=None, closing_balance=None, status=BankStatementStatus.PARSED); db.add(statement); await db.commit(); await db.refresh(statement); result = await validate_balance_chain(db, statement.id); assert result['closing_match'] is not True, 'closing_match reported True with no closing balance and no transactions (vacuous pass -> false confidence in the source review gate)'; assert result['closing_balance'] != 'None', "closing_balance serialized as the string 'None' (str(None)); should be JSON null or omitted"
